		CurrentStreak: activity.Stats.LifetimeCurrentStreak,
	}
	days := groupCommitsByDay(commits)

	sty := newActivityStyles(w)
	renderActivity(w, sty, stats, activity.Repos, activity.HourlyContributions, days)
	return nil
